<template><div class="page active" id="page-quiz"><div class="back-row"><button class="back-btn" @click="$emit('back')"><span class="icon"></span><span class="label">返回魔法店</span></button><span class="back-right"> 灵魂占卜</span></div><div class="page-title"><div class="main">灵魂问答</div><div class="sub">答 5 个问题，看穿你的胃</div></div><div class="quiz-progress"><span v-for="(_,index) in QUIZ_DATA" :key="index" class="dot" :class="{active:index===quizIndex && !showResult,done:index<quizIndex}"></span></div><div class="quiz-question" v-if="!showResult"><div class="q-text"><span class="q-num">第 {{ quizIndex + 1 }} / {{ QUIZ_DATA.length }} 题</span>{{ currentQuestion.question }}</div><div class="quiz-options"><button v-for="(opt,idx) in currentQuestion.options" :key="idx" class="opt-btn" @click="selectOption(opt.value)"><span class="opt-label">{{ labels[idx] }}</span>{{ opt.label }}</button></div></div><div class="quiz-question" v-else><div class="quiz-result-box"><div class="big-icon">{{ emoji }}</div><div class="result-name">{{ bestFood }}</div><div class="result-desc"> 灵魂占卜结果</div><div class="result-sub">今天就去吃 {{ bestFood }} 吧！</div><button class="restart-btn" @click="restartQuiz"> 再测一次</button></div></div><div class="footer-note" style="margin-top:6px">答案将指引你走向今日之食</div></div></template><script setup>import {ref,computed} from "vue";import {QUIZ_DATA,QUIZ_SCORES,QUIZ_FOODS,ALL_FOOD_NAMES,EMOJI_MAP} from "../data/foods";defineEmits(["back"]);const labels=["A","B","C"];const quizIndex=ref(0);const quizAnswers=ref([]);const showResult=ref(false);const bestFood=ref("火锅");const currentQuestion=computed(()=>QUIZ_DATA[quizIndex.value]);const emoji=computed(()=>EMOJI_MAP[bestFood.value]||"");function selectOption(value){quizAnswers.value.push(value);quizIndex.value++;if(quizIndex.value>=QUIZ_DATA.length){showQuizResult();}}function showQuizResult(){showResult.value=true;const scores={};QUIZ_FOODS.forEach(f=>scores[f]=0);quizAnswers.value.forEach(ans=>{const map=QUIZ_SCORES[ans]||{};Object.keys(map).forEach(food=>{if(scores[food]!==undefined){scores[food]+=map[food];}})});let maxScore=-1;for(const [food,score] of Object.entries(scores)){if(score>maxScore){maxScore=score;bestFood.value=food;}}}function restartQuiz(){quizIndex.value=0;quizAnswers.value=[];showResult.value=false;bestFood.value="火锅";}</script>